28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @Column(name = "membership_number")
68	    private String membershipNumber;
69	
70	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
71	    private Set<Pet> pets;
72	
73	    public String getAddress() {
74	        return this.address;
75	    }
76	
77	    public void setAddress(String address) {
78	        this.address = address;
79	    }
80	
81	    public String getCity() {
82	        return this.city;
83	    }
84	
85	    public void setCity(String city) {
86	        this.city = city;
87	    }
88	
89	    public String getTelephone() {
90	        return this.telephone;
91	    }
92	
93	    public void setTelephone(String telephone) {
94	        this.telephone = telephone;
95	    }
96	
97	    public String getEmail() {
98	        return this.email;
99	    }
100	
101	    public void setEmail(String email) {
102	        this.email = email;
103	    }
104	
105	    public LocalDate getRegistrationDate() {
106	        return this.registrationDate;
107	    }
108	
109	    public void setRegistrationDate(LocalDate registrationDate) {
110	        this.registrationDate = registrationDate;
111	    }
112	
113	    public String getCustomerCode() {
114	        return this.customerCode;
115	    }
116	
117	    public void setCustomerCode(String customerCode) {
118	        this.customerCode = customerCode;
119	    }
120	
121	    public String getHouseholdId() {
122	        return this.householdId;
123	    }
124	
125	    public void setHouseholdId(String householdId) {
126	        this.householdId = householdId;
127	    }
128	
129	    public Integer getNamesakeCount() {
130	        return this.namesakeCount;
131	    }
132	
133	    public void setNamesakeCount(Integer namesakeCount) {
134	        this.namesakeCount = namesakeCount;
135	    }
136	
137	    public String getMembershipNumber() {
138	        return this.membershipNumber;
139	    }
140	
141	    public void setMembershipNumber(String membershipNumber) {
142	        this.membershipNumber = membershipNumber;
143	    }
144	
145	    /**
146	     * The owner's locality: the canonical region derived from the city via the fixed
147	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), or
148	     * {@code "UNKNOWN"} for any other city. Derived from stored state, never persisted.
149	     */
150	    public String getLocality() {
151	        return CityLocality.forCity(this.city);
152	    }
153	
154	    /**
155	     * The owner's membership tier: {@code SILVER} when this owner had no namesakes at
156	     * creation ({@code namesakeCount} is 0) and has an email address, {@code BRONZE}
157	     * otherwise. Derived from stored state, never persisted.
158	     */
159	    public String getMembershipTier() {
160	        boolean silver = Integer.valueOf(0).equals(this.namesakeCount)
161	            && this.email != null && !this.email.isEmpty();
162	        return silver ? "SILVER" : "BRONZE";
163	    }
164	
165	    protected Set<Pet> getPetsInternal() {
166	        if (this.pets == null) {
167	            this.pets = new HashSet<>();
168	        }
169	        return this.pets;
170	    }
171	
172	    protected void setPetsInternal(Set<Pet> pets) {
173	        this.pets = pets;
174	    }
175	
176	    public List<Pet> getPets() {
177	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
178	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
179	        return Collections.unmodifiableList(sortedPets);
180	    }
181	
182	    public void setPets(List<Pet> pets) {
183	        this.pets = new HashSet<>(pets);
184	    }
185	
186	    public void addPet(Pet pet) {
187	        getPetsInternal().add(pet);
188	        pet.setOwner(this);
189	    }
190	
191	    /**
192	     * Return the Pet with the given name, or null if none found for this Owner.
193	     *
194	     * @param name to test
195	     * @return true if pet name is already in use
196	     */
197	    public Pet getPet(String name) {
198	        return getPet(name, false);
199	    }
200	
201	    /**
202	     * Return the Pet with the given name, or null if none found for this Owner.
203	     *
204	     * @param name to test
205	     * @return true if pet name is already in use
206	     */
207	    public Pet getPet(String name, boolean ignoreNew) {
208	        name = name.toLowerCase();
209	        for (Pet pet : getPetsInternal()) {
210	            if (!ignoreNew || !pet.isNew()) {
211	                String compName = pet.getName();
212	                compName = compName.toLowerCase();
213	                if (compName.equals(name)) {
214	                    return pet;
215	                }
216	            }
217	        }
218	        return null;
219	    }
220	
221	    public Pet getPet(Integer petId) {
222	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
223	    }
224	
225	    @Override
226	    public String toString() {
227	        return new ToStringCreator(this)
228	
229	            .append("id", this.getId())
230	            .append("new", this.isNew())
231	            .append("lastName", this.getLastName())
232	            .append("firstName", this.getFirstName())
233	            .append("address", this.address)
234	            .append("city", this.city)
235	            .append("telephone", this.telephone)
236	            .toString();
237	    }
238	}
